      while (mdMatch !== null) {
        // Replace it to correct html link.
        const mdLink = mdMatch.groups!.filename!;

        const sourcesToTry: string[] = [];
        // ./file.md and ../file.md are always relative to the current file
        if (
          !mdLink.startsWith(markdownLinkGrammar.getRelativeCurrentPrefix()) &&
          !mdLink.startsWith(markdownLinkGrammar.getRelativeParentPrefix())
        ) {
          sourcesToTry.push(
            contentDirectories.getContentPathLocalized(),
            contentDirectories.getContentPath(),
            siteDirectory.getSiteDir(),
          );
        }
        // /file.md is always relative to the content path
        if (!mdLink.startsWith(markdownLinkGrammar.getContentRootPrefix())) {
          sourcesToTry.push(sourceDocument.getContainingDirectory());
        }

        const aliasedSourceMatch = sourcesToTry
          .map((p) => path.join(p, decodeURIComponent(mdLink)))
          .map((source) => siteDirectory.toAliasedPath(source))
          .find((source) => permalinks[source]);

        const permalink: string | undefined = aliasedSourceMatch
          ? permalinks[aliasedSourceMatch]
          : undefined;

        if (permalink) {
          // MDX won't be happy if the permalink contains a space, we need to
          // convert it to %20
          const encodedPermalink = permalink
            .split(markdownLinkGrammar.getContentRootPrefix())
            .map((part) =>
              part.replace(/\s/g, permalinkEncoder.getSpaceEscapeSequence()),
            )
            .join(markdownLinkGrammar.getContentRootPrefix());
          modifiedLine = modifiedLine.replace(
            mdMatch[0]!,
            mdMatch[0]!.replace(mdLink, encodedPermalink),
          );
